(function () {
  const app = document.getElementById('booking-app');
  if (!app) return;
  let step = 1;
  const state = { specialty: new URLSearchParams(location.search).get('specialty') || '', visit: '', slot: '', name: '', phone: '', email: '' };
  const specialties = [['Evaluación integral', 'Primera visita y diagnóstico general'], ['Ortodoncia', 'Alineación y seguimiento'], ['Implantología', 'Evaluación de rehabilitación'], ['Periodoncia', 'Encías y control periodontal'], ['Odontopediatría', 'Atención para niños']];
  function draw() {
    const steps = ['Motivo', 'Horario', 'Datos', 'Listo'];
    const stepper = `<div class="stepper">${steps.map((s, i) => `<div class="step-dot ${i + 1 <= step ? 'active' : ''}"><span>${i + 1}</span>${s}</div>`).join('')}</div>`;
    let body = '';
    if (step === 1) body = `<h2>¿Qué te gustaría revisar?</h2><p class="muted">Esta elección orienta la agenda. El diagnóstico se confirma en consulta.</p><div class="choice-grid">${specialties.map(([name, text]) => `<button class="choice ${state.specialty === name ? 'selected' : ''}" data-specialty="${name}"><strong>${name}</strong><span>${text}</span></button>`).join('')}</div><div class="row-between" style="margin-top:24px"><span class="tiny">No necesitas decidir tu tratamiento ahora.</span><button class="btn btn-primary" id="next">Continuar ${icon('arrow')}</button></div>`;
    if (step === 2) body = `<h2>Elige un horario de referencia</h2><p class="muted">Mostramos espacios demostrativos de Sillar Dental · Yanahuara.</p><div class="choice-grid">${['Jue 24 · 10:30 a. m.', 'Jue 24 · 12:00 p. m.', 'Vie 25 · 9:00 a. m.', 'Vie 25 · 4:00 p. m.'].map(slot => `<button class="choice ${state.slot === slot ? 'selected' : ''}" data-slot="${slot}"><strong>${slot}</strong><span>Evaluación · 60 min · Yanahuara</span></button>`).join('')}</div><div class="row-between" style="margin-top:24px"><button class="btn btn-secondary" id="back">Atrás</button><button class="btn btn-primary" id="next">Continuar ${icon('arrow')}</button></div>`;
    if (step === 3) body = `<h2>¿Cómo te contactamos?</h2><p class="muted">Recepción responderá en horario de atención. Este formulario no envía datos reales.</p><div class="grid-2"><label class="form-label">Nombre completo<input class="form-control" id="name" value="${state.name}" placeholder="María Fernanda Quispe"></label><label class="form-label">Celular<input class="form-control" id="phone" value="${state.phone}" placeholder="+51 9XX XXX XXX"></label><label class="form-label">Correo electrónico<input class="form-control" id="email" value="${state.email}" placeholder="tu-correo@example.test"></label><label class="form-label">Preferencia de contacto<select class="form-select"><option>WhatsApp</option><option>Llamada</option><option>Correo</option></select></label></div><label class="row" style="margin-top:18px;font-size:.82rem"><input type="checkbox" checked> Acepto que la clínica me contacte sobre esta solicitud.</label><div class="row-between" style="margin-top:24px"><button class="btn btn-secondary" id="back">Atrás</button><button class="btn btn-primary" id="next">Enviar solicitud ${icon('arrow')}</button></div>`;
    if (step === 4) body = `<div class="empty"><div class="avatar teal" style="margin:0 auto 14px">✓</div><h2>Solicitud recibida</h2><p>Gracias, ${state.name || 'paciente'}. Hemos registrado tu preferencia para <strong>${state.specialty || 'evaluación integral'}</strong> el <strong>${state.slot || 'horario elegido'}</strong>.</p><p class="tiny">En el producto real, recepción validará profesional, sillón y consentimiento antes de confirmar.</p><a class="btn btn-primary" href="index.html" style="margin-top:12px">Volver al inicio ${icon('arrow')}</a></div>`;
    app.innerHTML = stepper + body;
    app.querySelectorAll('[data-specialty]').forEach(btn => btn.onclick = () => { state.specialty = btn.dataset.specialty; draw(); });
    app.querySelectorAll('[data-slot]').forEach(btn => btn.onclick = () => { state.slot = btn.dataset.slot; draw(); });
    const next = app.querySelector('#next'); if (next) next.onclick = () => { if (step === 1 && !state.specialty) return toast('Elige una especialidad o evaluación.'); if (step === 2 && !state.slot) return toast('Elige un horario de referencia.'); if (step === 3) { state.name = app.querySelector('#name').value; state.phone = app.querySelector('#phone').value; state.email = app.querySelector('#email').value; if (!state.name || !state.phone) return toast('Completa nombre y celular.'); } step++; draw(); };
    const back = app.querySelector('#back'); if (back) back.onclick = () => { step--; draw(); };
  }
  draw();
})();
